  1	/**
  2	 * Settings View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders two settings sections:
  5	 *   1. **Git Credentials** — table of per-host PATs with add/delete controls.
  6	 *   2. **Repositories Refresh Delay** — number input for `gitPollingIntervalSeconds`
  7	 *      with client-side validation (min 10) and save/feedback.
  8	 *
  9	 * This view has no side-effects (no polling), so it returns no cleanup function.
 10	 *
 11	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
 12	 * @param {Object}      _params   - Route params (none for this route).
 13	 */
 14	
 15	import { api } from '../api.js';
 16	import { showToast } from '../components/toast.js';
 17	import { showConfirm } from '../components/confirm-dialog.js';
 18	import { createFormField, validateRequired } from '../components/form-helpers.js';
 19	
 20	// ---------------------------------------------------------------------------
 21	// Table rendering
 22	// ---------------------------------------------------------------------------
 23	
 24	/**
 25	 * Build the `<thead>` for the credentials table.
 26	 *
 27	 * @returns {HTMLElement}
 28	 */
 29	function buildTableHead() {
 30	    const thead = document.createElement('thead');
 31	    const tr = document.createElement('tr');
 32	
 33	    ['Host', 'Token', 'Actions'].forEach((label) => {
 34	        const th = document.createElement('th');
 35	        th.textContent = label;
 36	        tr.appendChild(th);
 37	    });
 38	
 39	    thead.appendChild(tr);
 40	    return thead;
 41	}
 42	
 43	/**
 44	 * Build a single `<tr>` for one credential entry.
 45	 *
 46	 * @param {string}            host       - The hostname key.
 47	 * @param {string}            maskedToken - The masked token string (e.g. `****abc1`).
 48	 * @param {function(): void}  onDeleted  - Callback to refresh the table after deletion.
 49	 * @returns {HTMLTableRowElement}
 50	 */
 51	function buildCredentialRow(host, maskedToken, onDeleted) {
 52	    const tr = document.createElement('tr');
 53	    tr.dataset.credHost = host;
 54	
 55	    // ---- Host cell (read-only) ----
 56	    const hostCell = document.createElement('td');
 57	    hostCell.className = 'cred-host-cell';
 58	    hostCell.textContent = host;
 59	    tr.appendChild(hostCell);
 60	
 61	    // ---- Masked token cell (read-only) ----
 62	    const tokenCell = document.createElement('td');
 63	    tokenCell.className = 'cred-token-cell text-muted';
 64	    tokenCell.textContent = maskedToken;
 65	    tr.appendChild(tokenCell);
 66	
 67	    // ---- Actions cell ----
 68	    const actionsCell = document.createElement('td');
 69	    actionsCell.className = 'cred-actions-cell';
 70	
 71	    const deleteBtn = document.createElement('button');
 72	    deleteBtn.type = 'button';
 73	    deleteBtn.className = 'btn btn-danger btn-sm';
 74	    deleteBtn.textContent = 'Delete';
 75	
 76	    actionsCell.appendChild(deleteBtn);
 77	    tr.appendChild(actionsCell);
 78	
 79	    // ---- Behaviour ----
 80	
 81	    deleteBtn.addEventListener('click', async () => {
 82	        try {
 83	            await showConfirm(
 84	                'Delete Credential',
 85	                `Remove the credential for "${host}"? This action cannot be undone.`,
 86	            );
 87	        } catch {
 88	            // User cancelled — do nothing.
 89	            return;
 90	        }
 91	
 92	        deleteBtn.disabled = true;
 93	        deleteBtn.textContent = 'Deleting…';
 94	
 95	        try {
 96	            await api.config.credentials.delete(host);
 97	            showToast(`Credential for "${host}" deleted.`, 'success');
 98	            onDeleted();
 99	        } catch (err) {
100	            showToast(err.message || 'Failed to delete credential.', 'error');

101	            deleteBtn.disabled = false;
102	            deleteBtn.textContent = 'Delete';
103	        }
104	    });
105	
106	    return tr;
107	}
108	
109	// ---------------------------------------------------------------------------
110	// Credentials table rendering
111	// ---------------------------------------------------------------------------
112	
113	/**
114	 * Render a loading indicator into `tableContainer`.
115	 *
116	 * @param {HTMLElement} tableContainer
117	 */
118	function showLoading(tableContainer) {
119	    tableContainer.innerHTML = `
120	        <div class="loading-indicator" aria-live="polite" aria-label="Loading credentials…">
121	            <span class="spinner" aria-hidden="true"></span>
122	            <span>Loading credentials…</span>
123	        </div>
124	    `;
125	}
126	
127	/**
128	 * Fetch all credentials and render them into `tableContainer`.
129	 *
130	 * @param {HTMLElement} tableContainer
131	 */
132	async function renderCredentialsTable(tableContainer) {
133	    showLoading(tableContainer);
134	
135	    let credentials;
136	    try {
137	        credentials = await api.config.credentials.list();
138	    } catch (err) {
139	        tableContainer.innerHTML = '';
140	        const errorP = document.createElement('p');
141	        errorP.className = 'error-message';
142	        errorP.setAttribute('role', 'alert');
143	        errorP.textContent = `Failed to load credentials: ${err.message || 'Unknown error'}`;
144	        tableContainer.appendChild(errorP);
145	        return;
146	    }
147	
148	    const entries = Object.entries(credentials || {});
149	
150	    if (entries.length === 0) {
151	        tableContainer.innerHTML = `
152	            <p class="empty-state">No credentials configured. Use the form below to add one.</p>
153	        `;
154	        return;
155	    }
156	
157	    const table = document.createElement('table');
158	    table.className = 'credentials-table';
159	    table.setAttribute('role', 'table');
160	    table.setAttribute('aria-label', 'Git credentials');
161	
162	    table.appendChild(buildTableHead());
163	
164	    const tbody = document.createElement('tbody');
165	
166	    for (const [host, maskedToken] of entries) {
167	        tbody.appendChild(buildCredentialRow(host, maskedToken, () => {
168	            renderCredentialsTable(tableContainer);
169	        }));
170	    }
171	
172	    table.appendChild(tbody);
173	    tableContainer.innerHTML = '';
174	    tableContainer.appendChild(table);
175	}
176	
177	// ---------------------------------------------------------------------------
178	// Add / Update credential form
179	// ---------------------------------------------------------------------------
180	
181	/**
182	 * Build the "Add / Update Credential" section with a toggle button and inline form.
183	 *
184	 * @param {HTMLElement} tableContainer - Used to trigger a refresh after a successful save.
185	 * @returns {HTMLElement} The wrapper element containing the toggle button and form.
186	 */
187	function buildAddCredentialForm(tableContainer) {
188	    const section = document.createElement('div');
189	    section.className = 'add-credential-section';
190	
191	    const toggleBtn = document.createElement('button');
192	    toggleBtn.type = 'button';
193	    toggleBtn.className = 'btn btn-primary';
194	    toggleBtn.textContent = 'Add / Update Credential';
195	
196	    const formWrapper = document.createElement('div');
197	    formWrapper.className = 'form-wrapper';
198	    formWrapper.hidden = true;
199	
200	    const form = document.createElement('form');
201	    form.noValidate = true;
202	
203	    form.appendChild(createFormField('Host', 'text', 'host', {
204	        placeholder: 'e.g. github.com',
205	        required: true,
206	    }));
207	
208	    form.appendChild(createFormField('Token', 'password', 'token', {
209	        placeholder: 'Personal access token',
210	        required: true,
211	    }));
212	
213	    const actions = document.createElement('div');
214	    actions.className = 'form-actions';
215	
216	    const submitBtn = document.createElement('button');
217	    submitBtn.type = 'submit';
218	    submitBtn.className = 'btn btn-primary';
219	    submitBtn.textContent = 'Save';
220	
221	    const cancelBtn = document.createElement('button');
222	    cancelBtn.type = 'button';
223	    cancelBtn.className = 'btn btn-secondary';
224	    cancelBtn.textContent = 'Cancel';
225	
226	    actions.appendChild(submitBtn);
227	    actions.appendChild(cancelBtn);
228	    form.appendChild(actions);
229	    formWrapper.appendChild(form);
230	
231	    section.appendChild(toggleBtn);
232	    section.appendChild(formWrapper);
233	
234	    // ---- Behaviour ----
235	
236	    toggleBtn.addEventListener('click', () => {
237	        formWrapper.hidden = !formWrapper.hidden;
238	        if (!formWrapper.hidden) {
239	            const hostInput = form.querySelector('[name="host"]');
240	            if (hostInput) hostInput.focus();
241	        }
242	    });
243	
244	    cancelBtn.addEventListener('click', () => {
245	        form.reset();
246	        formWrapper.hidden = true;
247	    });
248	
249	    form.addEventListener('submit', async (e) => {
250	        e.preventDefault();
251	
252	        if (!validateRequired(form, ['host', 'token'])) return;
253	
254	        const host  = form.querySelector('[name="host"]').value.trim();
255	        const token = form.querySelector('[name="token"]').value.trim();
256	
257	        submitBtn.disabled = true;
258	        submitBtn.textContent = 'Saving…';
259	
260	        try {
261	            await api.config.credentials.set({ host, token });
262	            showToast(`Credential for "${host}" saved.`, 'success');
263	            form.reset();
264	            formWrapper.hidden = true;
265	            renderCredentialsTable(tableContainer);
266	        } catch (err) {
267	            showToast(err.message || 'Failed to save credential.', 'error');
268	        } finally {
269	            submitBtn.disabled = false;
270	            submitBtn.textContent = 'Save';
271	        }
272	    });
273	
274	    return section;
275	}
276	
277	// ---------------------------------------------------------------------------
278	// Repositories Refresh Delay section
279	// ---------------------------------------------------------------------------
280	
281	/**
282	 * Build the "Repositories Refresh Delay" section.
283	 *
284	 * Fetches the current server-side `gitPollingIntervalSeconds` value on mount,
285	 * populates a number input, and persists changes via `PUT /api/config/polling`.
286	 *
287	 * Client-side validation rejects values below 10 without sending a request.
288	 * A success or error toast is shown after every save attempt.
289	 *
290	 * @returns {HTMLElement} The section wrapper element.
291	 */
292	function buildRefreshDelaySection() {
293	    const section = document.createElement('div');
294	    section.className = 'refresh-delay-section';
295	
296	    const heading = document.createElement('h2');
297	    heading.textContent = 'Repositories Refresh Delay';
298	    section.appendChild(heading);
299	
300	    const description = document.createElement('p');
301	    description.textContent =
302	        'How often (in seconds) the server polls remote repositories for new commits. ' +
303	        'Changes take effect immediately — the current polling cycle is restarted with the new interval. ' +
304	        'Minimum value is 10 seconds.';
305	    section.appendChild(description);
306	
307	    // ---- Input row ----
308	    const inputRow = document.createElement('div');
309	    inputRow.className = 'refresh-delay-input-row';
310	
311	    const label = document.createElement('label');
312	    label.htmlFor = 'refresh-delay-input';
313	    label.textContent = 'Interval';
314	    label.className = 'refresh-delay-label';
315	
316	    const input = document.createElement('input');
317	    input.type = 'number';
318	    input.id = 'refresh-delay-input';
319	    input.name = 'refreshDelay';
320	    input.className = 'form-input refresh-delay-input';
321	    input.min = '10';
322	    input.step = '1';
323	    input.placeholder = '30';
324	    input.setAttribute('aria-label', 'Polling interval in seconds');
325	
326	    const unitLabel = document.createElement('span');
327	    unitLabel.className = 'refresh-delay-unit';
328	    unitLabel.textContent = 'seconds';
329	
330	    const saveBtn = document.createElement('button');
331	    saveBtn.type = 'button';
332	    saveBtn.className = 'btn btn-primary';
333	    saveBtn.textContent = 'Save';
334	
335	    inputRow.appendChild(label);
336	    inputRow.appendChild(input);
337	    inputRow.appendChild(unitLabel);
338	    inputRow.appendChild(saveBtn);
339	    section.appendChild(inputRow);
340	
341	    // ---- Inline error message ----
342	    const errorMsg = document.createElement('p');
343	    errorMsg.className = 'error-message';
344	    errorMsg.setAttribute('role', 'alert');
345	    errorMsg.hidden = true;
346	    section.appendChild(errorMsg);
347	
348	    // ---- Populate current value on mount ----
349	    (async () => {
350	        try {
351	            const cfg = await api.config.polling.get();
352	            if (cfg && typeof cfg.gitPollingIntervalSeconds === 'number') {
353	                input.value = String(cfg.gitPollingIntervalSeconds);
354	            }
355	        } catch {
356	            // Non-fatal — leave the placeholder in place.
357	        }
358	    })();
359	
360	    // ---- Save behaviour ----
361	    saveBtn.addEventListener('click', async () => {
362	        const raw   = input.value.trim();
363	        const value = Number(raw);
364	
365	        // Client-side validation.
366	        if (!raw || !Number.isFinite(value) || !Number.isInteger(value) || value < 10) {
367	            errorMsg.textContent = 'Please enter a whole number of 10 or more.';
368	            errorMsg.hidden = false;
369	            input.focus();
370	            return;
371	        }
372	
373	        errorMsg.hidden = true;
374	        saveBtn.disabled = true;
375	        saveBtn.textContent = 'Saving…';
376	
377	        try {
378	            await api.config.polling.set(value);
379	            showToast('Refresh delay saved.', 'success');
380	        } catch (err) {
381	            showToast(err.message || 'Failed to save refresh delay.', 'error');
382	        } finally {
383	            saveBtn.disabled = false;
384	            saveBtn.textContent = 'Save';
385	        }
386	    });
387	
388	    return section;
389	}
390	
391	// ---------------------------------------------------------------------------
392	// View entry point
393	// ---------------------------------------------------------------------------
394	
395	/**
396	 * Render the Settings view into `container`.
397	 *
398	 * No cleanup function is returned because this view has no side-effects:
399	 * it does not start polling, install global event listeners, or hold any
400	 * external resources. The router does not need to call a teardown. This

401	 * is consistent with the `repositories` view, which follows the same pattern.
402	 *
403	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
404	 * @param {Object}      _params   - Route params (none for this route).
405	 * @returns {void}
406	 */
407	export function renderSettings(container, _params) {
408	    container.innerHTML = '';
409	
410	    // Page heading
411	    const heading = document.createElement('h1');
412	    heading.textContent = 'Settings';
413	    container.appendChild(heading);
414	
415	    // Credentials section
416	    const credHeading = document.createElement('h2');
417	    credHeading.textContent = 'Git Credentials';
418	    container.appendChild(credHeading);
419	
420	    const credDescription = document.createElement('p');
421	    credDescription.textContent =
422	        'Manage per-host personal access tokens used for authenticating with private repositories. Tokens are stored masked — only the last 4 characters are visible.';
423	    container.appendChild(credDescription);
424	
425	    const tableContainer = document.createElement('div');
426	    tableContainer.className = 'credentials-table-container';
427	    container.appendChild(tableContainer);
428	
429	    container.appendChild(buildAddCredentialForm(tableContainer));
430	
431	    // Initial data load
432	    renderCredentialsTable(tableContainer);
433	
434	    // ---- Refresh Delay section ----
435	    container.appendChild(buildRefreshDelaySection());
436	}

  1	import { test } from 'node:test';
  2	import assert from 'node:assert/strict';
  3	import * as fs from 'node:fs';
  4	import * as os from 'os';
  5	import * as path from 'node:path';
  6	import { EventEmitter } from 'node:events';
  7	import type { IncomingMessage, ServerResponse } from 'node:http';
  8	import { Router } from '../../router.js';
  9	import { registerConfigRoutes } from '../../routes/config.js';
 10	import type { AppConfig } from '../../../config/config.types.js';
 11	import type { PollingManager } from '../../pollingManager.js';
 12	
 13	// ---------------------------------------------------------------------------
 14	// Temp dir (cleaned up on process exit)
 15	// ---------------------------------------------------------------------------
 16	
 17	const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'paralizer-config-routes-test-'));
 18	
 19	process.on('exit', () => {
 20	    fs.rmSync(tmpRoot, { recursive: true, force: true });
 21	});
 22	
 23	// ---------------------------------------------------------------------------
 24	// Mock helpers (same pattern as other route tests)
 25	// ---------------------------------------------------------------------------
 26	
 27	function mockRequest(method: string, url: string, bodyJson?: unknown): IncomingMessage {
 28	    const req = new EventEmitter() as IncomingMessage;
 29	    (req as unknown as { method: string }).method = method;
 30	    (req as unknown as { url: string }).url = url;
 31	    (req as unknown as { destroy(): void }).destroy = () => {
 32	        req.emit('error', new Error('destroyed'));
 33	    };
 34	
 35	    process.nextTick(() => {
 36	        if (bodyJson !== undefined) {
 37	            req.emit('data', Buffer.from(JSON.stringify(bodyJson)));
 38	        }
 39	        req.emit('end');
 40	    });
 41	
 42	    return req;
 43	}
 44	
 45	interface MockResponse {
 46	    statusCode: number | undefined;
 47	    body: string;
 48	    res: ServerResponse;
 49	}
 50	
 51	function mockResponse(): MockResponse {
 52	    const mock: MockResponse = {
 53	        statusCode: undefined,
 54	        body: '',
 55	        res: null as unknown as ServerResponse,
 56	    };
 57	
 58	    const res = new EventEmitter() as unknown as ServerResponse;
 59	
 60	    (res as unknown as {
 61	        writeHead(status: number, headers?: Record<string, string | number>): void;
 62	    }).writeHead = (status: number) => {
 63	        mock.statusCode = status;
 64	    };
 65	
 66	    (res as unknown as { end(body?: string): void }).end = (body?: string) => {
 67	        mock.body = body ?? '';
 68	    };
 69	
 70	    mock.res = res;
 71	    return mock;
 72	}
 73	
 74	// ---------------------------------------------------------------------------
 75	// Test fixture helpers
 76	// ---------------------------------------------------------------------------
 77	
 78	/**
 79	 * Creates a minimal valid config.json in a temp subdirectory.
 80	 * Returns the absolute path to the config file.
 81	 */
 82	function makeConfigFile(initial: Record<string, unknown> = {}): string {
 83	    const dir = fs.mkdtempSync(path.join(tmpRoot, 'cfg-'));
 84	    const configPath = path.join(dir, 'config.json');
 85	    const base = {
 86	        projectsFolder: dir,
 87	        storageFolder: dir,
 88	        cloneDepth: 50,
 89	        serverPort: 4200,
 90	        gitPollingIntervalSeconds: 30,
 91	        ...initial,
 92	    };
 93	    fs.writeFileSync(configPath, JSON.stringify(base));
 94	    return configPath;
 95	}
 96	
 97	function makeAppConfig(overrides: Partial<AppConfig> = {}): AppConfig {
 98	    return {
 99	        projectsFolder: tmpRoot,
100	        storageFolder: tmpRoot,

101	        cloneDepth: 50,
102	        serverPort: 4200,
103	        gitPollingIntervalSeconds: 30,
104	        ...overrides,
105	    };
106	}
