118	/**
119	 * Creates a minimal PollingManager stub that records restart() calls.
120	 */
121	function makeMockPollingManager(): PollingManager & { restartCalls: number[]; } {
122	    const stub = {
123	        restartCalls: [] as number[],
124	        restart(intervalSeconds: number): void {
125	            stub.restartCalls.push(intervalSeconds);
126	        },
127	    };
128	    return stub as unknown as PollingManager & { restartCalls: number[]; };
129	}
